output_text:
[
  {
    "id": "no_cart_single_file_shelf_aisle",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves border both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "An agent must not enter a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "single_file_no_lateral_moves",
    "text": "Inside a single-file shelf aisle, movement must stay along the aisle rather than sideways into shelves or across the aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          {
            "or": [
              "E",
              "W"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_wide_travel",
    "text": "Except at designated cart-parking mouths, an agent should not move through wide shopping aisles without their cart.",
    "abstraction": {
      "state_properties": {
        "openCartAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "wideTravelAreaAwayFromCartMouth": {
          "and": [
            "openCartAisle",
            {
              "not": "cartParkingMouth"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          "wideTravelAreaAwayFromCartMouth"
        ]
      }
    }
  },
  {
    "id": "retrieve_before_open_departure",
    "text": "After returning to a cart-parking mouth, an agent must not leave into the open aisle without first taking the cart back.",
    "abstraction": {
      "state_properties": {
        "openCartAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "leaveParkingMouthCartlessIntoOpen": {
          "pre": {
            "and": [
              "cartParkingMouth",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "openCartAisle",
              {
                "not": "singleFileShelfAisle"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leaveParkingMouthCartlessIntoOpen"
    }
  },
  {
    "id": "parked_cart_must_be_reclaimed",
    "text": "Whenever an agent parks or releases a cart, they are obliged to reclaim a cart before the trip ends.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCart",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "lower_north_shelf_flow",
    "text": "At lower-aisle service positions with a shelf immediately north, carts should leave only eastward along the aisle or southward away from the shelf, not north or west.",
    "abstraction": {
      "state_properties": {
        "lowerNorthShelfServiceCell": {
          "and": [
            "adjShelf",
            "shelfN",
            {
              "le": [
                "freeWidthV",
                2
              ]
            },
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "lowerNorthShelfServiceCell",
          {
            "or": [
              "N",
              "W"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "eastbound_cart_traffic",
    "text": "In wide horizontal shopping aisles, cart traffic is one-way eastbound, so pushing a cart west is prohibited.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "wideHorizontalAisle",
          "W"
        ]
      }
    }
  }
]
